Sub 'PrintFilters'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
If &GridState.DynamicFilters.Count >= 1 &GridStateDynamicFilter = &GridState.DynamicFilters.Item(1) &DynamicFiltersSelector1 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector1 = !'TIPAJUNOME' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &tipajuNome1.FromString(&GridStateDynamicFilter.Value) If not &tipajuNome1.IsEmpty() Do Case Case &DynamicFiltersOperator1 = 0 &FiltertipajuNomeDescription = format('%1 (%2)', "Tipo", "WWP_FilterLike") Case &DynamicFiltersOperator1 = 1 &FiltertipajuNomeDescription = format('%1 (%2)', "Tipo", "WWP_FilterContains") EndCase &tipajuNome = &tipajuNome1 print printBlockFiltertipajuNome EndIf Case &DynamicFiltersSelector1 = !'AJUSLOCADESCRICAO' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &ajusLocaDescricao1.FromString(&GridStateDynamicFilter.Value) If not &ajusLocaDescricao1.IsEmpty() Do Case Case &DynamicFiltersOperator1 = 0 &FilterajusLocaDescricaoDescription = format('%1 (%2)', "Local", "WWP_FilterLike") Case &DynamicFiltersOperator1 = 1 &FilterajusLocaDescricaoDescription = format('%1 (%2)', "Local", "WWP_FilterContains") EndCase &ajusLocaDescricao = &ajusLocaDescricao1 print printBlockFilterajusLocaDescricao EndIf Case &DynamicFiltersSelector1 = !'AJUSCODIGO' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &ajusCodigo1.FromString(&GridStateDynamicFilter.Value) If not &ajusCodigo1.IsEmpty() Do Case Case &DynamicFiltersOperator1 = 0 &FilterajusCodigoDescription = format('%1 (%2)', "Código", "=") EndCase &ajusCodigo = &ajusCodigo1 print printBlockFilterajusCodigo EndIf EndCase If &GridState.DynamicFilters.Count >= 2 &DynamicFiltersEnabled2 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(2) &DynamicFiltersSelector2 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector2 = !'TIPAJUNOME' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &tipajuNome2.FromString(&GridStateDynamicFilter.Value) If not &tipajuNome2.IsEmpty() Do Case Case &DynamicFiltersOperator2 = 0 &FiltertipajuNomeDescription = format('%1 (%2)', "Tipo", "WWP_FilterLike") Case &DynamicFiltersOperator2 = 1 &FiltertipajuNomeDescription = format('%1 (%2)', "Tipo", "WWP_FilterContains") EndCase &tipajuNome = &tipajuNome2 print printBlockFiltertipajuNome EndIf Case &DynamicFiltersSelector2 = !'AJUSLOCADESCRICAO' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &ajusLocaDescricao2.FromString(&GridStateDynamicFilter.Value) If not &ajusLocaDescricao2.IsEmpty() Do Case Case &DynamicFiltersOperator2 = 0 &FilterajusLocaDescricaoDescription = format('%1 (%2)', "Local", "WWP_FilterLike") Case &DynamicFiltersOperator2 = 1 &FilterajusLocaDescricaoDescription = format('%1 (%2)', "Local", "WWP_FilterContains") EndCase &ajusLocaDescricao = &ajusLocaDescricao2 print printBlockFilterajusLocaDescricao EndIf Case &DynamicFiltersSelector2 = !'AJUSCODIGO' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &ajusCodigo2.FromString(&GridStateDynamicFilter.Value) If not &ajusCodigo2.IsEmpty() Do Case Case &DynamicFiltersOperator2 = 0 &FilterajusCodigoDescription = format('%1 (%2)', "Código", "=") EndCase &ajusCodigo = &ajusCodigo2 print printBlockFilterajusCodigo EndIf EndCase If &GridState.DynamicFilters.Count >= 3 &DynamicFiltersEnabled3 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(3) &DynamicFiltersSelector3 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector3 = !'TIPAJUNOME' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &tipajuNome3.FromString(&GridStateDynamicFilter.Value) If not &tipajuNome3.IsEmpty() Do Case Case &DynamicFiltersOperator3 = 0 &FiltertipajuNomeDescription = format('%1 (%2)', "Tipo", "WWP_FilterLike") Case &DynamicFiltersOperator3 = 1 &FiltertipajuNomeDescription = format('%1 (%2)', "Tipo", "WWP_FilterContains") EndCase &tipajuNome = &tipajuNome3 print printBlockFiltertipajuNome EndIf Case &DynamicFiltersSelector3 = !'AJUSLOCADESCRICAO' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &ajusLocaDescricao3.FromString(&GridStateDynamicFilter.Value) If not &ajusLocaDescricao3.IsEmpty() Do Case Case &DynamicFiltersOperator3 = 0 &FilterajusLocaDescricaoDescription = format('%1 (%2)', "Local", "WWP_FilterLike") Case &DynamicFiltersOperator3 = 1 &FilterajusLocaDescricaoDescription = format('%1 (%2)', "Local", "WWP_FilterContains") EndCase &ajusLocaDescricao = &ajusLocaDescricao3 print printBlockFilterajusLocaDescricao EndIf Case &DynamicFiltersSelector3 = !'AJUSCODIGO' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &ajusCodigo3.FromString(&GridStateDynamicFilter.Value) If not &ajusCodigo3.IsEmpty() Do Case Case &DynamicFiltersOperator3 = 0 &FilterajusCodigoDescription = format('%1 (%2)', "Código", "=") EndCase &ajusCodigo = &ajusCodigo3 print printBlockFilterajusCodigo EndIf EndCase EndIf EndIf EndIf If not (&TFajusCodigo.IsEmpty() AND &TFajusCodigo_To.IsEmpty()) print printBlockTFajusCodigo &TFajusCodigo_To_Description = format('%1 (%2)', "Código", "WWP_TSTo") print printBlockTFajusCodigo_To EndIf If not (&TFajusData.IsEmpty() AND &TFajusData_To.IsEmpty()) print printBlockTFajusData &TFajusData_To_Description = format('%1 (%2)', "Data", "WWP_TSTo") print printBlockTFajusData_To EndIf If not &TFtipajuCodigo_Sel.IsEmpty() print printBlockTFtipajuCodigo_Sel Else If not &TFtipajuCodigo.IsEmpty() print printBlockTFtipajuCodigo EndIf EndIf &TFtipajuAcao_Sels.FromJson(&TFtipajuAcao_SelsJson) If not &TFtipajuAcao_Sels.Count = 0 &i = 1 For &TFtipajuAcao_Sel in &TFtipajuAcao_Sels If &i = 1 &TFtipajuAcao_SelDscs = '' Else &TFtipajuAcao_SelDscs += ', ' EndIf &FilterTFtipajuAcao_SelValueDescription = &TFtipajuAcao_Sel.EnumerationDescription()
&TFtipajuAcao_SelDscs += &FilterTFtipajuAcao_SelValueDescription &i += 1 EndFor print printBlockTFtipajuAcao_Sel EndIf If not &TFajusLocaCodigo_Sel.IsEmpty() print printBlockTFajusLocaCodigo_Sel Else If not &TFajusLocaCodigo.IsEmpty() print printBlockTFajusLocaCodigo EndIf EndIf
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'PrintColumnTitles'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
print printBlockBeforeGrid print printBlockLines_titles
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'PrintData'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
For each trnsajuste order tipajuNome when &OrderedBy = 1 order ajusCodigo when &OrderedBy = 2 AND &OrderedDsc = False order (ajusCodigo) when &OrderedBy = 2 AND &OrderedDsc = True order ajusData when &OrderedBy = 3 AND &OrderedDsc = False order (ajusData) when &OrderedBy = 3 AND &OrderedDsc = True order tipajuCodigo when &OrderedBy = 4 AND &OrderedDsc = False order (tipajuCodigo) when &OrderedBy = 4 AND &OrderedDsc = True order tipajuAcao when &OrderedBy = 5 AND &OrderedDsc = False order (tipajuAcao) when &OrderedBy = 5 AND &OrderedDsc = True order ajusLocaCodigo when &OrderedBy = 6 AND &OrderedDsc = False order (ajusLocaCodigo) when &OrderedBy = 6 AND &OrderedDsc = True
using trnsajusteWWDS(&DynamicFiltersSelector1, &DynamicFiltersOperator1, &tipajuNome1, &ajusLocaDescricao1, &ajusCodigo1, &DynamicFiltersEnabled2 , &DynamicFiltersSelector2, &DynamicFiltersOperator2, &tipajuNome2, &ajusLocaDescricao2, &ajusCodigo2, &DynamicFiltersEnabled3 , &DynamicFiltersSelector3, &DynamicFiltersOperator3, &tipajuNome3, &ajusLocaDescricao3, &ajusCodigo3, &TFajusCodigo , &TFajusCodigo_To, &TFajusData, &TFajusData_To, &TFtipajuCodigo, &TFtipajuCodigo_Sel, &TFtipajuAcao_Sels , &TFajusLocaCodigo, &TFajusLocaCodigo_Sel) Where prefCodigo = &prefCodigo &tipajuAcaoDescription = tipajuAcao.EnumerationDescription()
Do 'BeforePrintLine' If ajusStatus = 'C' print printBlockLines_data_2 Else print printBlockLines_data EndIf
Do 'AfterPrintLine' EndFor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'LoadGridState'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
// Load grid state from session. If &Session.Get(!"trnsajusteWWGridState") = !"" &GridState.FromXml(LoadGridState.Udp(!"trnsajusteWWGridState")) Else &GridState.FromXml(&Session.Get(!"trnsajusteWWGridState")) Endif
&OrderedBy = &GridState.OrderedBy &OrderedDsc = &GridState.OrderedDsc
For &GridStateFilterValue in &GridState.FilterValues Do Case Case &GridStateFilterValue.Name = !"TFAJUSCODIGO" &TFajusCodigo.FromString(&GridStateFilterValue.Value) &TFajusCodigo_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFAJUSDATA" &TFajusData.FromString(&GridStateFilterValue.Value) &TFajusData_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFTIPAJUCODIGO" &TFtipajuCodigo.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFTIPAJUCODIGO_SEL" &TFtipajuCodigo_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFTIPAJUACAO_SEL" &TFtipajuAcao_SelsJson = &GridStateFilterValue.Value &TFtipajuAcao_Sels.FromJson(&TFtipajuAcao_SelsJson) Case &GridStateFilterValue.Name = !"TFAJUSLOCACODIGO" &TFajusLocaCodigo.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFAJUSLOCACODIGO_SEL" &TFajusLocaCodigo_Sel.FromString(&GridStateFilterValue.Value) EndCase EndFor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
